"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1010-08-15:0":{"b": ["Valencia beralih ke tangan budak yang dimerdekakan Amiriyah, Mubarak dan Muzaffar", "38ac8e22"], "d": ["Dengan runtuhnya kekuasaan cucu-cucu Hajib Mansur, Valencia masuk ke pemerintahan Mubarak dan Muzaffar, budak yang dimerdekakan Amiriyah; emirat taifa mulai muncul di Andalusia.", "82f013cc"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1013-01-01:0":{"b": ["Sulayman al-Musta'in dan para pendukungnya memasuki Cordoba dan kembali menurunkan Hisham II dari takhta; sedikitnya enam puluh ulama dibunuh di kota (403/1013; sumber memberikan tahun, tanpa hari).", "e863c0b4"], "d": ["Sulayman al-Musta'in dan para pendukungnya memasuki Cordoba dan kembali menurunkan Hisham II dari takhta; sedikitnya enam puluh ulama dibunuh di kota (403/1013; sumber memberikan tahun, tanpa hari).", "e863c0b4"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1016-01-01:0":{"b": ["Hammudiyah merebut Cordoba dan takhta Andalusia", "a8a8ea65"], "d": ["Hammudiyah Syiah, yang mengaku keturunan Alawi, memanfaatkan kelemahan dinasti Umayyah dan merebut Cordoba serta takhta khilafah pada 1016; Cordoba tetap di bawah kekuasaan mereka antara 1016-1022.", "b088ab2a"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1021-01-01:0":{"b": ["Dinasti Amiriyah didirikan dengan pusat Valencia (1021-1094)", "ebf0b6e2"], "d": ["Abdulaziz b. Abdurrahman, cucu Hajib al-Mansur, pada 1021 mendirikan emirat taifa Amiriyah dengan pusat Valencia; dinasti berlangsung dengan beberapa selingan hingga 1094.", "dc1ccee5"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1023-03-26:0":{"b": ["Qadi Ibn Abbad memproklamasikan Seville pusat pemerintahan (Abbadiyah)", "931db55e"], "d": ["Qadi Abu al-Qasim Ibn Abbad memproklamasikan Seville pusat pemerintahan pada 414 (1023); emirat taifa Abbadiyah menjadi salah satu pusat terpenting Andalusia.", "51e3b6d5"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1031-01-01:0":{"b": ["Cordoba menjadi republik di bawah pemerintahan Jahwariyah (1031-1070)", "943bc77c"], "d": ["Setelah berakhirnya dinasti Umayyah, Cordoba menjadi republik di bawah pemerintahan Jahwariyah dari 1031 hingga 1070.", "6afd1a28"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1049-06-05:0":{"b": ["Ketika wazir Fatimiyah al-Yazuri mengangkat kepala Zughba sebagai emir Tripoli dan Qabis, Bani Hilal bergerak ke barat (441, 1049).", "481a1144"], "d": ["Ketika wazir Fatimiyah al-Yazuri mengangkat kepala Zughba sebagai emir Tripoli dan Qabis, Bani Hilal bergerak ke barat (441, 1049).", "481a1144"]},
